__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"techniques",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"categories",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"techniqueById",{enumerable:!0,get:function(){return n}});const o=[{id:'vibrato',name:'Vibrato',category:'Adornos y afinaci\xf3n',color:'#3D63DD',level:'Intermedio',summary:'Una oscilaci\xf3n regular y suave de la afinaci\xf3n sobre una nota sostenida.',whatIs:'El vibrato es una peque\xf1a ondulaci\xf3n de la altura de la nota, de unas 5 a 7 veces por segundo, que aparece cuando la voz sostiene una nota de forma libre y apoyada. No se fabrica moviendo la mand\xedbula o la garganta: surge cuando hay equilibrio entre el aire y el cierre de las cuerdas vocales.',howTo:['Sost\xe9n una nota c\xf3moda en tu registro medio con buen apoyo de aire.','Relaja mand\xedbula, lengua y cuello; la nota debe sentirse libre, no apretada.','Deja que la nota ondule ligeramente, sin forzarla. Al principio puedes alternar dos notas muy cercanas despacio.','Apl\xedcalo al final de las frases largas, que es donde m\xe1s se usa.'],commonMistakes:['Mover la mand\xedbula o la cabeza para "fabricar" la ondulaci\xf3n.','Un vibrato demasiado ancho o lento, que suena a temblor.','Ponerlo en todas las notas, tambi\xe9n en las cortas.'],exercises:[{title:'Alternancia lenta de semitono',steps:['Elige una nota c\xf3moda (por ejemplo, Do4) y la nota de un semitono m\xe1s arriba.','Alterna entre las dos con la vocal "u" a 2 cambios por segundo durante 8 segundos.','Sube poco a poco a 4 y luego a 6 cambios por segundo, sin cortar el aire.','Reduce la distancia hasta que dejes de sentir dos notas y oigas una sola que ondula.']},{title:'Nota larga con vibrato al final',steps:['Canta una nota recta durante 4 tiempos.','En los 4 tiempos siguientes, suelta la tensi\xf3n y deja aparecer el vibrato.','Repite en 5 notas distintas de tu registro.']},{title:'Vibrato con pulsos de aire',steps:['Con la boca cerrada (humming), da peque\xf1os impulsos suaves desde el abdomen.','Acelera los impulsos hasta que se unan en una ondulaci\xf3n continua.','Abre a la vocal "a" manteniendo la sensaci\xf3n.']}],tutorials:[{videoId:'_LWlrBlrh3M',title:'C\xf3mo cantar con vibrato: ejercicios (1/3)',language:'es'},{videoId:'w_HpI-bhrYI',title:'\xbfC\xf3mo hacer vibrato con la voz? \xbfQu\xe9 es el vibrato?',language:'es'},{videoId:'R79AVrbOvAE',title:'How To Sing With Vibrato',language:'en'}],sources:[{label:'Vibrato (Wikipedia)',url:'https://es.wikipedia.org/wiki/Vibrato'}]},{id:'glissando',name:'Glissando',category:'Adornos y afinaci\xf3n',color:'#0E8F80',level:'B\xe1sico',summary:'Un deslizamiento continuo de la voz que recorre todas las alturas entre dos notas.',whatIs:'En el glissando la voz "resbala" de una nota a otra pasando por todas las alturas intermedias, como una sirena. Se usa como efecto expresivo y, sobre todo, como ejercicio para unir los registros de la voz sin saltos.',howTo:['Empieza en una nota grave c\xf3moda.','Desliza la voz hacia arriba de forma continua, sin escalones, hasta una nota aguda.','Mant\xe9n el mismo volumen y el mismo aire durante todo el recorrido.','Haz el camino de vuelta hacia abajo con la misma suavidad.'],commonMistakes:['Hacer "escalones" en lugar de un deslizamiento continuo.','Empujar m\xe1s aire o subir el volumen al llegar al agudo.','Romper la voz en el paso de registro en vez de suavizarlo.'],exercises:[{title:'Sirena con labios (lip trill)',steps:['Haz vibrar los labios como una moto ("brrr").','Sin parar la vibraci\xf3n, desliza la voz de grave a agudo y de vuelta.','Repite 5 veces, ampliando poco a poco el recorrido.']},{title:'Sirena en "ng"',steps:['Coloca la lengua como al decir "ng" (de "tengo").','Desliza de una quinta a la octava arriba y vuelve.','F\xedjate en que el paso por el registro medio no tenga saltos.']},{title:'Glissando de quinta con vocal',steps:['Canta Do4 en "a" y desliza hasta Sol4.','Sube medio tono y repite, hasta donde est\xe9s c\xf3modo.']}],tutorials:[{videoId:'FbafpUT66-w',title:'Canto: glissando y portamento',language:'es'},{videoId:'hFkZCweeU9g',title:'Glissando vocal exercise',language:'en'},{videoId:'uMpSZB4T6bs',title:'Glissando 1a: transici\xf3n suave entre registros',language:'en'}],sources:[{label:'Glissando (Wikipedia)',url:'https://es.wikipedia.org/wiki/Glissando'}]},{id:'portamento',name:'Portamento',category:'Adornos y afinaci\xf3n',color:'#C25E00',level:'Intermedio',summary:'Un enlace breve y expresivo entre dos notas, "llevando" la voz de una a otra.',whatIs:'El portamento es parecido al glissando, pero m\xe1s corto y musical: la voz se desliza solo al final de una nota para llegar a la siguiente, casi siempre en la misma s\xedlaba o al cambiar de s\xedlaba. Da sensaci\xf3n de ternura o de dramatismo, y es muy t\xedpico del bolero, la ranchera y la canci\xf3n l\xedrica.',howTo:['Canta la primera nota con su duraci\xf3n normal.','Justo antes de cambiar, desliza r\xe1pidamente hacia la nota siguiente.','Llega afinado y qu\xe9date en la nueva nota sin "rebotar".'],commonMistakes:['Usarlo en todas las notas: pierde efecto y suena desafinado.','Deslizar demasiado despacio y llegar tarde a la nota.','Pasarse de la nota de llegada y corregir despu\xe9s.'],exercises:[{title:'Terceras ligadas',steps:['Canta Do4 y Mi4 en la vocal "o", con un portamento corto entre ellas.','Repite bajando de Mi4 a Do4.','Practica con terceras, cuartas y quintas.']},{title:'Portamento en una frase',steps:['Elige una frase lenta de una canci\xf3n que te guste.','Marca dos lugares donde un portamento tendr\xeda sentido (finales de palabra).','C\xe1ntala primero sin portamento y despu\xe9s con \xe9l, y compara.']}],tutorials:[{videoId:'FbafpUT66-w',title:'Canto: glissando y portamento',language:'es'},{videoId:'YfKqAI2_nOo',title:'How to Portamento',language:'en'}],sources:[{label:'Portamento (Wikipedia)',url:'https://es.wikipedia.org/wiki/Portamento'}]},{id:'melisma',name:'Melisma',category:'Adornos y afinaci\xf3n',color:'#D12F7A',level:'Avanzado',summary:'Varias notas cantadas sobre una misma s\xedlaba.',whatIs:'Un melisma es un grupo de notas distintas que se cantan sobre una sola s\xedlaba. Va desde un adorno de dos notas hasta las "carreras" (runs y riffs) del pop, el soul o el flamenco. Requiere agilidad: cambiar de nota r\xe1pido sin perder afinaci\xf3n ni aire.',howTo:['Aprende primero las notas del melisma despacio, una a una.','C\xe1ntalas en la vocal de la s\xedlaba, sin volver a articular consonantes.','Sube la velocidad poco a poco, con metr\xf3nomo, sin perder claridad.'],commonMistakes:['Ir r\xe1pido antes de que las notas est\xe9n claras: se vuelve un borr\xf3n.','A\xf1adir "h" entre notas (ha-ha-ha) en lugar de ligarlas.','Cerrar la garganta en las notas r\xe1pidas.'],exercises:[{title:'Escala de cinco notas',steps:['Canta Do-Re-Mi-Fa-Sol-Fa-Mi-Re-Do en una sola "a", a 60 BPM.','Sube a 80, 100 y 120 BPM solo cuando salga limpio.','Sube medio tono y repite.']},{title:'Escala pentat\xf3nica (el "run" del pop)',steps:['Canta la pentat\xf3nica menor bajando: La-Sol-Mi-Re-Do-La.','Hazla primero en negras, luego en corcheas y luego en semicorcheas.']},{title:'Copiar un adorno',steps:['Escucha un melisma corto de una canci\xf3n y ralent\xedzalo.','Escribe o tararea las notas una a una.','Vuelve a la velocidad original por pasos.']}],tutorials:[{videoId:'4-mbqr7m3q0',title:'\xbfC\xf3mo cantar melismas? 5 pasos',language:'es'},{videoId:'tX5g1s_b9HQ',title:'T\xe9cnica para runs, riffs y melismas',language:'es'},{videoId:'ZqfO6j5gNoE',title:'How to Sing Riffs, Melismas and Runs Smoothly',language:'en'}],sources:[{label:'Melisma (Wikipedia)',url:'https://es.wikipedia.org/wiki/Melisma'}]},{id:'falsete',name:'Falsete',category:'Registros',color:'#7445D6',level:'Intermedio',summary:'Un registro ligero y aireado que permite llegar a notas agudas con suavidad.',whatIs:'El falsete es un modo de vibraci\xf3n en el que solo vibra el borde de las cuerdas vocales. Suena m\xe1s ligero y aireado que la voz de pecho y permite notas agudas sin esfuerzo. En la m\xfasica mexicana se usa el "quiebre": pasar de golpe de la voz de pecho al falsete.',howTo:['Imita el sonido de un b\xfaho ("uuu") en una nota aguda y suave.','Mant\xe9n poco volumen y la laringe relajada.','Practica despu\xe9s el paso de voz de pecho a falsete en la misma vocal.'],commonMistakes:['Apretar la garganta para subir m\xe1s.','Confundirlo con gritar en el agudo.','No practicar el paso entre registros, que es donde se rompe la voz.'],exercises:[{title:'El b\xfaho',steps:['Di "uuu" como un b\xfaho en una nota aguda y suave.','Baja deslizando la voz sin cambiar la sensaci\xf3n ligera.','Repite 5 veces.']},{title:'Quiebre pecho-falsete',steps:['Canta una nota media en voz de pecho con la vocal "a".','Salta una quinta arriba en falsete, en la misma vocal.','Repite hasta que el paso sea limpio y controlado.']}],tutorials:[{videoId:'2QVVaE2wYZk',title:'C\xf3mo cantar falsete o voz de cabeza desde cero',language:'es'},{videoId:'o94BpiOLcRE',title:'Ejercicios de canto: falsete o voz de cabeza',language:'es'},{videoId:'gH_QhApA-ao',title:'Mariachi vocal tutorial: how to sing falsetto',language:'en'}],sources:[{label:'Falsete (Wikipedia)',url:'https://es.wikipedia.org/wiki/Falsete'}]},...r(d[0]).extraTechniques],s=['Adornos y afinaci\xf3n','Registros','Color y emisi\xf3n','Articulaci\xf3n y din\xe1mica'],n=s=>o.find(o=>o.id===s)},820,[852]);
